def run_task(task, models, validate, evaluate):
    candidate = models.route(task)
    result = candidate.generate(task.prompt)

    if not validate(result, task.schema):
        result = models.repair_route(task).generate(task.prompt, prior=result)

    if not evaluate(result, task.acceptance_check):
        raise RuntimeError("Result requires review")

    return result
